package com.casystem.onboarding.model;import jakarta.persistence.*;import lombok.*;import java.time.LocalDateTime;@Entity @Table(name="documents") @Getter @Setter @NoArgsConstructor public class Document{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;private Long userId;private String fileName;private String contentType;@Column(columnDefinition="bytea") private byte[] encryptedContent;private boolean deleted=false;private LocalDateTime createdAt=LocalDateTime.now();}